        const nose = new Mesh(new ConeGeometry(r * 0.14, r * 0.4, 8), S3);
        nose.rotation.x = Math.PI / 2 - 0.25;
        nose.position.set(0, r * 1.18, r * 1);
        g2.add(nose);
        const brow = new Mesh(new CapsuleGeometry(r * 0.09, r * 0.8, 3, 8), S3);
